assert set(SLIDES) == set(DEMO) and len(SLIDES) == 21
for lang, slides in SLIDES.items():
    assert len(slides) == 9, lang
    copy = {"lang": lang, "dir": "rtl" if lang == 'ar' else "ltr", "slides": {}}
    path = os.path.join(HERE, 'copy', f'{lang}.json')
    old = json.load(open(path, encoding='utf-8')) if os.path.exists(path) else {}
    for key, (pill, title, sub, c1, c2) in zip(ORDER, slides):
        slide = {"pill": pill, "title": title, "sub": sub, "chips": [list(c1), list(c2)]}
        if 's' in old.get('slides', {}).get(key, {}): slide['s'] = old['slides'][key]['s']  # mock screen texts (az only)
        copy['slides'][key] = slide
    if 'nav' in old: copy['nav'] = old['nav']
    json.dump(copy, open(path, 'w', encoding='utf-8'), ensure_ascii=False, indent=2); open(path, 'a').write('\n')
    demo_dir = os.path.join(HERE, 'real-app', 'demo'); os.makedirs(demo_dir, exist_ok=True)
    json.dump(DEMO[lang], open(os.path.join(demo_dir, f'{lang}.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
print('wrote', len(SLIDES), 'languages')
